SELECT COUNT(*)
FROM reservations
WHERE room_id = #{roomId}
  AND reservation_status IN ('booked', 'checked_in')
  AND check_in_date < #{checkOutDate}
  AND check_out_date > #{checkInDate}

SELECT COUNT(*)
FROM reservations
WHERE room_id = #{roomId}
  AND reservation_status IN ('booked', 'checked_in')
  AND id != #{excludedReservationId}
  AND check_in_date < #{checkOutDate}
  AND check_out_date > #{checkInDate}

SELECT COUNT(*)
FROM reservations
WHERE room_id = #{roomId}
  AND reservation_status IN ('booked', 'checked_in')
  AND id != #{excludedReservationId}
  AND check_in_date <= #{stayDate}
  AND check_out_date > #{stayDate}

